	// lfs f0,2144(r9)
	ctx.fpscr.disableFlushMode();
	temp.u32 = REX_LOAD_U32(ctx.r9.u32 + 2144);
	ctx.f0.f64 = double(temp.f32);
	// lfs f13,-27840(r8)
	temp.u32 = REX_LOAD_U32(ctx.r8.u32 + -27840);
